class Solution {
public:
    int countSquares(std::vector<std::vector<int>>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        int ans = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (matrix[r][c] == 1 && r > 0 && c > 0) {
                    matrix[r][c] = 1 + std::min({matrix[r - 1][c], matrix[r][c - 1], matrix[r - 1][c - 1]});
                }
                ans += matrix[r][c];
            }
        }
        return ans;
    }
};

class Solution {
    public int countSquares(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int ans = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (matrix[r][c] == 1 && r > 0 && c > 0) {
                    matrix[r][c] = 1 + Math.min(matrix[r - 1][c], Math.min(matrix[r][c - 1], matrix[r - 1][c - 1]));
                }
                ans += matrix[r][c];
            }
        }
        return ans;
    }
}

var countSquares = function(matrix) {
    const m = matrix.length, n = matrix[0].length;
    let ans = 0;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (matrix[r][c] === 1 && r > 0 && c > 0) {
                matrix[r][c] = 1 + Math.min(matrix[r - 1][c], matrix[r][c - 1], matrix[r - 1][c - 1]);
            }
            ans += matrix[r][c];
        }
    }
    return ans;
};
